import { inlineSvg } from "@/lib/inline-svg";

/** Files in public/. The projects/ ones are the per-card drawings; the three
 *  bare names are the homepage doors; the rough/ ones are generated by
 *  scripts/gen-rough.mjs. inlineSvg resolves and refuses anything outside
 *  public/, so the slash here is safe. */
export type FigureName =
  | "gradient-descent"
  | "blog-backprop"
  | "agent-loop"
  | `projects/${string}`
  | `rough/${string}`;

/**
 * An SVG from public/, inlined.
 *
 * Server component, no client JS. The hand-authored figures animate in CSS
 * inside the file; the generated rough/ marks carry no styling at all and are
 * driven entirely from globals.css, which is only reachable because an inlined
 * svg is not the document root.
 *
 * Each file carries its own <title>/<desc> and role, so nothing is added here.
 */
export function Figure({
  name,
  className,
}: {
  name: FigureName;
  className?: string;
}) {
  return (
    <span
      className={className}
      dangerouslySetInnerHTML={{ __html: inlineSvg(name) }}
    />
  );
}
